"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { signOut, useSession } from "next-auth/react";
import {
  Heart,
  Home,
  Search,
  Plus,
  MessageSquare,
  User,
  LogOut,
  Bookmark,
  Package,
  Shield,
  Map,
  Gift,
  Lightbulb,
} from "lucide-react";

const navItems = [
  { href: "/dashboard", label: "Dashboard", icon: Home },
  { href: "/gemachs", label: "Browse Gemachs", icon: Search },
  { href: "/map", label: "Map View", icon: Map },
  { href: "/needs", label: "Needs Feed", icon: Gift },
  { href: "/dashboard/my-gemachs", label: "My Gemachs", icon: Heart },
  { href: "/dashboard/new", label: "Add Gemach", icon: Plus },
  { href: "/dashboard/requests", label: "Requests", icon: Package },
  { href: "/dashboard/messages", label: "Messages", icon: MessageSquare },
  { href: "/dashboard/saved", label: "Saved", icon: Bookmark },
  { href: "/dashboard/suggestions", label: "Suggestions", icon: Lightbulb },
  { href: "/dashboard/profile", label: "Profile", icon: User },
  { href: "/admin", label: "Admin", icon: Shield },
];

export function Sidebar() {
  const pathname = usePathname();
  const { data: session } = useSession();

  return (
    <aside className="flex h-full w-64 flex-shrink-0 flex-col border-r border-gray-800 bg-gray-900">
      {/* Logo */}
      <div className="flex items-center gap-2 px-4 py-5 border-b border-gray-800">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary-600">
          <Heart className="h-5 w-5 text-white" />
        </div>
        <span className="text-lg font-bold text-white">Gemach Connect</span>
      </div>

      {/* Navigation */}
      <nav className="flex-1 space-y-0.5 overflow-y-auto px-3 py-4">
        {navItems.map((item) => {
          const active = pathname === item.href;
          return (
            <Link
              key={item.href}
              href={item.href}
              className={`flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition ${
                active
                  ? "bg-gray-800 text-white"
                  : "text-gray-400 hover:bg-gray-800 hover:text-gray-200"
              }`}
            >
              <item.icon className="h-5 w-5 flex-shrink-0" />
              {item.label}
            </Link>
          );
        })}
      </nav>

      {/* User */}
      {session?.user && (
        <div className="border-t border-gray-800 px-4 py-4 space-y-3">
          <div className="text-sm">
            <p className="font-medium text-gray-200 truncate">{session.user.name}</p>
            <p className="text-gray-500 truncate text-xs">{session.user.email}</p>
          </div>
          <button
            onClick={() => signOut({ callbackUrl: "/" })}
            className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-sm text-gray-400 transition hover:bg-gray-800 hover:text-gray-200"
          >
            <LogOut className="h-4 w-4" /> Sign Out
          </button>
        </div>
      )}
    </aside>
  );
}

import { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import bcrypt from "bcryptjs";
import { prisma } from "./prisma";

export const authOptions: NextAuthOptions = {
  providers: [
    CredentialsProvider({
      name: "credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) return null;

        const user = await prisma.user.findUnique({
          where: { email: credentials.email },
        });

        if (!user) return null;

        const valid = await bcrypt.compare(credentials.password, user.password);
        if (!valid) return null;

        return { id: user.id, email: user.email, name: user.name, phone: user.phone, city: user.city, state: user.state, bio: user.bio };
      },
    }),
  ],
  session: { strategy: "jwt" },
  pages: { signIn: "/login" },
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = user.id;
        token.phone = (user as any).phone;
        token.city = (user as any).city;
        token.state = (user as any).state;
        token.bio = (user as any).bio;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.id;
        session.user.phone = token.phone as string | null;
        session.user.city = token.city as string | null;
        session.user.state = token.state as string | null;
        session.user.bio = token.bio as string | null;
      }
      return session;
    },
  },
  secret: process.env.NEXTAUTH_SECRET || "dev-secret-change-me-in-production-min-32-chars",
};

import { PrismaClient } from "@prisma/client";

const globalForPrisma = globalThis as unknown as { prisma: PrismaClient };

export const prisma = globalForPrisma.prisma || new PrismaClient();

if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function GET(_req: Request, { params }: { params: { id: string } }) {
  const gemach = await prisma.gemach.findUnique({
    where: { id: params.id },
    include: { owner: { select: { id: true, name: true, email: true, phone: true } } },
  });

  if (!gemach) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  return NextResponse.json({ gemach });
}

export async function PUT(req: Request, { params }: { params: { id: string } }) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const gemach = await prisma.gemach.findUnique({ where: { id: params.id } });
  if (!gemach) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  if (gemach.ownerId !== session.user.id) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const body = await req.json();
  const updated = await prisma.gemach.update({
    where: { id: params.id },
    data: body,
  });

  return NextResponse.json({ gemach: updated });
}

export async function DELETE(req: Request, { params }: { params: { id: string } }) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const gemach = await prisma.gemach.findUnique({ where: { id: params.id } });
  if (!gemach) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  if (gemach.ownerId !== session.user.id) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  await prisma.gemach.delete({ where: { id: params.id } });
  return NextResponse.json({ success: true });
}

